insert into public.cards (id, owner_id, data) values
('d49ae754-7f53-567e-80d7-3ec021115bc8', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d49ae754-7f53-567e-80d7-3ec021115bc8", "code": "11ER-064", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "oxydant", "réducteur", "méthode"], "front": "Comment **justifier** qu''une espèce est l''oxydant ou le réducteur d''un couple ?", "back": "On écrit la demi-équation et on regarde les électrons.\nEx. : $\\mathrm{Cu^{2+} + 2\\,e^- = Cu}$ : $\\mathrm{Cu^{2+}}$ **capte** des électrons, c''est l''oxydant ; $\\mathrm{Cu}$ peut en **céder**, c''est le réducteur.", "createdAt": 1793568696089, "updatedAt": 1793568696089, "ocrDone": true}'::jsonb),
('7750d1f7-ef6d-5081-8869-4ee7718a298e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7750d1f7-ef6d-5081-8869-4ee7718a298e", "code": "11ER-065", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "demi-équation", "exemple"], "front": "**Exemple** : demi-équation du couple $\\mathrm{I_2 / I^-}$ ?", "back": "$\\mathrm{I_2 + 2\\,e^- = 2\\,I^-}$\nOn équilibre d''abord l''élément iode, puis les charges avec les électrons.", "createdAt": 1793568696090, "updatedAt": 1793568696090, "ocrDone": true}'::jsonb),
('ee379fcd-0e76-5ed1-a5b8-2e917fae9879', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ee379fcd-0e76-5ed1-a5b8-2e917fae9879", "code": "11ER-066", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "oxydo-réduction", "exemple"], "front": "**Exemple** : équation de la réaction entre $\\mathrm{Al}$ et $\\mathrm{H^+}$ (couples $\\mathrm{Al^{3+}/Al}$ et $\\mathrm{H^+/H_2}$) ?", "back": "$\\mathrm{Al = Al^{3+} + 3\\,e^-}$ ($\\times 2$)\n$\\mathrm{2\\,H^+ + 2\\,e^- = H_2}$ ($\\times 3$)\n$\\mathrm{2\\,Al + 6\\,H^+ \\to 2\\,Al^{3+} + 3\\,H_2}$", "createdAt": 1793568696091, "updatedAt": 1793568696091, "ocrDone": true}'::jsonb),
('c9f9d402-35cc-5b4e-967c-0877826eaf3b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c9f9d402-35cc-5b4e-967c-0877826eaf3b", "code": "11ER-067", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "réactif limitant"], "front": "Définir le **réactif limitant**.", "back": "Le réactif entièrement consommé en premier : sa disparition arrête la transformation.", "createdAt": 1793568696092, "updatedAt": 1793568696092, "ocrDone": true}'::jsonb),
('916bbd22-0763-50cf-ad62-5eeb480ff042', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "916bbd22-0763-50cf-ad62-5eeb480ff042", "code": "11ER-068", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "réactif limitant", "piège"], "front": "Pourquoi ne peut-on pas trouver le limitant en comparant simplement $n_A$ et $n_B$ ?", "back": "Il faut tenir compte des nombres stœchiométriques : on compare $\\dfrac{n_A}{a}$ et $\\dfrac{n_B}{b}$.\nEx. : pour $\\mathrm{A + 2\\,B}$, avec $n_A = 2$ mol et $n_B = 3$ mol, on compare 2 et 1,5 : **B** est limitant, bien que $n_B \\gt n_A$.", "createdAt": 1793568696093, "updatedAt": 1793568696093, "ocrDone": true}'::jsonb),
('728e9a26-4df8-5e57-aab1-dc7a1103f809', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "728e9a26-4df8-5e57-aab1-dc7a1103f809", "code": "11ER-069", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "avancement"], "front": "Quelle différence entre $x_{\\max}$ et $x_f$ ?", "back": "**$x_{\\max}$** se **calcule** : c''est l''avancement si le réactif limitant est entièrement consommé.\n**$x_f$** se **déduit de l''état final réel** (description ou mesure).", "createdAt": 1793568696094, "updatedAt": 1793568696094, "ocrDone": true}'::jsonb),
('ce1f530f-e0e5-5ea5-b68e-b1437b8ba0d8', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ce1f530f-e0e5-5ea5-b68e-b1437b8ba0d8", "code": "11ER-070", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "état final", "méthode"], "front": "Méthode : **composition de l''état final** d''une transformation totale ?", "back": "1. Calculer les quantités initiales en mol.\n2. Construire le tableau d''avancement.\n3. Trouver $x_{\\max}$ (plus petite valeur).\n4. Remplacer $x_f$ par $x_{\\max}$ dans la dernière ligne, pour chaque espèce.", "createdAt": 1793568696095, "updatedAt": 1793568696095, "ocrDone": true}'::jsonb),
('5fb55f78-aa00-5607-8a9b-906806c6cadc', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "5fb55f78-aa00-5607-8a9b-906806c6cadc", "code": "11ER-071", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "état final", "exemple"], "front": "**Exemple** : $\\mathrm{Zn + 2\\,H^+ \\to Zn^{2+} + H_2}$ avec $0{,}020$ mol de $\\mathrm{Zn}$ et $0{,}025$ mol de $\\mathrm{H^+}$. Transformation totale : état final ?", "back": "$x_{\\max}$ : $0{,}020$ mol pour $\\mathrm{Zn}$ ; $\\dfrac{0{,}025}{2} = 0{,}0125$ mol pour $\\mathrm{H^+}$.\nDonc $x_{\\max} = 0{,}0125$ mol, $\\mathrm{H^+}$ limitant.\nÉtat final : $\\mathrm{Zn}$ : $0{,}0075$ mol ; $\\mathrm{H^+}$ : 0 ; $\\mathrm{Zn^{2+}}$ et $\\mathrm{H_2}$ : $0{,}0125$ mol.", "createdAt": 1793568696096, "updatedAt": 1793568696096, "ocrDone": true}'::jsonb),
('1a564aeb-8f97-5ed3-93f8-4eb429717397', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1a564aeb-8f97-5ed3-93f8-4eb429717397", "code": "11ER-072", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "avancement", "méthode"], "front": "Méthode : déterminer $x_f$ à partir de la **description de l''état final** ?", "back": "1. Repérer la quantité finale d''une espèce (donnée ou mesurée).\n2. L''égaler à son expression dans le tableau (ex. : $n_{\\text{produit}} = c\\,x_f$).\n3. Comparer $x_f$ à $x_{\\max}$ : égaux, transformation totale ; $x_f \\lt x_{\\max}$, non totale.", "createdAt": 1793568696097, "updatedAt": 1793568696097, "ocrDone": true}'::jsonb),
('f20fe51e-c2e6-597c-871b-8b37004a5c37', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "f20fe51e-c2e6-597c-871b-8b37004a5c37", "code": "11ER-073", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Matière", "tags": ["1re", "Matière", "cours", "état final", "expérience"], "front": "**Expérience** : quelles mesures permettent de trouver une quantité de matière à l''état final ?", "back": "**Masse** : $n = \\dfrac{m}{M}$\n**Volume de gaz** : $n = \\dfrac{V}{V_m}$\n**Absorbance** : $A = k\\,C$, puis $n = C \\times V$", "createdAt": 1793568696098, "updatedAt": 1793568696098, "ocrDone": true}'::jsonb);
